                                /** @enum {string} */
                                readonly issuer: "prestocks" | "xstocks" | "tessera";
                                readonly issuerProductId: string;
                                readonly symbol: string;
                                readonly name: string;
                                readonly companyName: string;
                                /** @enum {string} */
                                readonly kind: "pre_ipo_exposure" | "listed_stock";
